 /** Server accepted the op: the item becomes `saved` (server copy, new version) and the op is dropped. Unknown opId returns `state` itself. */
 export function resolveOp(state: State, opId: string, saved: Item): State {
-  return state;
+  const op = state.pending.find((o) => o.opId === opId);
+  if (!op) return state;
+  const items = state.items.map((item) => (item.id === op.id ? saved : item));
+  return { ...state, items, pending: state.pending.filter((o) => o.opId !== opId) };
 }

