@@ -45,7 +56,15 @@ export function resolveOp(state: State, opId: string, saved: Item): State {
  * Unknown opId returns `state` itself.
  */
 export function rejectOp(state: State, opId: string, error: ApiErrorBody): State {
-  return state;
+  const op = state.pending.find((o) => o.opId === opId);
+  if (!op) return state;
+  const conflict = error.code === 'version_conflict' && error.current !== undefined;
+  const replacement = conflict ? (error.current as Item) : op.prev;
+  const items = state.items.map((item) => (item.id === op.id ? replacement : item));
+  const banner = conflict
+    ? `Conflict: "${(error.current as Item).title}" was changed elsewhere. Showing the latest version.`
+    : error.message;
+  return { ...state, items, pending: state.pending.filter((o) => o.opId !== opId), banner };
 }

